function validate([nums, k, numOperations]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100,000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value of nums is a whole number from 1 to 100,000.';
  if (!Number.isInteger(k) || k < 0 || k > 100000) return 'k is a whole number from 0 to 100,000.';
  if (!Number.isInteger(numOperations) || numOperations < 0 || numOperations > nums.length) return 'numOperations is between 0 and the length of nums.';
  return null;
}

