function maxFrequency(nums, k, numOperations) {
  const maxValue = Math.max(...nums);
  const count = new Array(maxValue + 1).fill(0);
  for (const num of nums) {
    count[num]++;
  }
  const prefix = new Array(maxValue + 2).fill(0);
  for (let v = 0; v <= maxValue; v++) {
    prefix[v + 1] = prefix[v] + count[v];
  }

  let best = 0;
  for (let target = 1; target <= maxValue; target++) {
    const low = Math.max(0, target - k);
    const high = Math.min(maxValue, target + k);
    const reachable = prefix[high + 1] - prefix[low];
    const frequency = Math.min(reachable, count[target] + numOperations);
    best = Math.max(best, frequency);
  }
  return best;
}

