function maxFrequency(nums, k, numOperations) {
  // Try every value some element could be moved to, and count directly who is already there and who can reach it.
  const lowest = Math.min(...nums) - k, highest = Math.max(...nums) + k;
  let best = 0;
  for (let target = lowest; target <= highest; target++) {
    let same = 0, near = 0;
    for (const x of nums) {
      if (x === target) same++;
      else if (Math.abs(x - target) <= k) near++;
    }
    best = Math.max(best, same + Math.min(near, numOperations));
  }
  return best;
}

