function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  if (size === 'large') {
    const n = 2000, top = [100000, 20000, 2000][pick(3)];
    const nums = Array.from({ length: n }, () => 1 + pick(top));
    const k = rand() < 0.2 ? pick(3) : pick(Math.floor(top / 50) + 1);
    return [nums, k, pick(n + 1)];
  }
  // Small: a few values packed into a narrow band, sometimes at the top of the allowed range.
  const n = 1 + pick(8), span = 1 + pick(20);
  const base = rand() < 0.2 ? 100001 - span : 1;
  const nums = Array.from({ length: n }, () => base + pick(span));
  const k = rand() < 0.08 ? 100000 : pick(7);
  return [nums, k, pick(n + 1)];
}
